Shortest Path:
import heapq
n,m=map(int,input().split());g=[[] for _ in range(n+1)]
for _ in range(m):
    u,v,w=map(int,input().split());g[u].append((v,w));g[v].append((u,w))
INF=float('inf');d=[INF]*(n+1);d[1]=0;h=[(0,1)]
while h:
    x,u=heapq.heappop(h)
    if x>d[u]: continue
    for v,w in g[u]:
        if x+w<d[v]: d[v]=x+w;heapq.heappush(h,(d[v],v))
print(d[n] if d[n]<INF else -1)

Smallest Topological Order:
import heapq
n,m=map(int,input().split());g=[[] for _ in range(n+1)];d=[0]*(n+1)
for _ in range(m):
    u,v=map(int,input().split());g[u].append(v);d[v]+=1
h=[i for i in range(1,n+1) if d[i]==0];heapq.heapify(h);o=[]
while h:
    u=heapq.heappop(h);o.append(u)
    for v in g[u]:
        d[v]-=1
        if d[v]==0: heapq.heappush(h,v)
print(*o) if len(o)==n else print('IMPOSSIBLE')

